function currency(n: number) {
  return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(n || 0);
}

function parseCurrencyInput(value: string): number {
  // Remove non-digit characters
  const digits = value.replace(/[^0-9]/g, '');
  return digits ? parseInt(digits, 10) : 0;
}

function formatCurrencyInput(n: number): string {
  return currency(n);
}

function enumerateMonths(from: string, to: string): string[] {
  const res: string[] = [];
  const [fy, fm] = from.split('-').map(Number);
  const [ty, tm] = to.split('-').map(Number);
  if (!fy || !fm || !ty || !tm) return res;
  let y = fy, m = fm;
  while (y < ty || (y === ty && m <= tm)) {
    res.push(`${y}-${String(m).padStart(2,'0')}`);
    m += 1;
    if (m > 12) { m = 1; y += 1; }
  }
  return res;
}

function sanitizeFilename(value: string): string {
  return value.replace(/[\\/:*?"<>|]/g, '').replace(/\s+/g, ' ').trim();
}

// DEBUG MODE: set true to generate PDF only without updating VPS item/invoice data in backend.
const VPS_INVOICE_PRINT_ONLY = false;

const INVOICE_PROGRAM_PREFIX = 'BIAYA BERLANGGANAN ONLINE &\nMAINTENANCE';
const INVOICE_STORE_SUFFIX_PREFIX = 'TOKO EMAS';

function formatInvoiceProgramName(
  programName: string,
  options?: { includeStoreSuffix?: boolean; storeName?: string }
): string {
  const cleaned = (programName || '').trim();
  const base = cleaned ? `${INVOICE_PROGRAM_PREFIX} ${cleaned}` : INVOICE_PROGRAM_PREFIX;
  if (!options?.includeStoreSuffix) {
    return base.replace(/\s*\n+\s*/g, ' ').replace(/\s{2,}/g, ' ').trim();
  }
  const store = (options.storeName || '').trim();
  const withSuffix = store ? `${base} ${INVOICE_STORE_SUFFIX_PREFIX} ${store}` : base;
  return withSuffix.replace(/\s*\n+\s*/g, ' ').replace(/\s{2,}/g, ' ').trim();
}

function generateLocalInvoiceNumber(dateIso: string): string {
  const d = new Date(dateIso || new Date().toISOString());
  const yy = String(d.getFullYear()).slice(-2);
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  const monthKey = `${d.getFullYear()}-${mm}`;
  const storageKey = 'vps_invoice_counter_monthly';
  let nextCounter = 1;
  try {
    const raw = typeof window !== 'undefined' ? window.localStorage.getItem(storageKey) : null;
    if (raw) {
      const parsed = JSON.parse(raw) as { monthKey?: string; counter?: number };
      if (parsed?.monthKey === monthKey) {
        nextCounter = (Number(parsed.counter) || 0) + 1;
      }
    }
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(storageKey, JSON.stringify({ monthKey, counter: nextCounter }));
    }
  } catch {
    nextCounter = 1;
  }
  return `${yy}/${mm}/${dd}/${String(nextCounter).padStart(4, '0')}`;
}

function toIndonesianWords(value: number): string {
  const angka = ['', 'satu', 'dua', 'tiga', 'empat', 'lima', 'enam', 'tujuh', 'delapan', 'sembilan', 'sepuluh', 'sebelas'];
  const n = Math.floor(Math.abs(value));
  if (n < 12) return angka[n];
  if (n < 20) return `${toIndonesianWords(n - 10)} belas`;
  if (n < 100) return `${toIndonesianWords(Math.floor(n / 10))} puluh ${toIndonesianWords(n % 10)}`.trim();
  if (n < 200) return `seratus ${toIndonesianWords(n - 100)}`.trim();
  if (n < 1000) return `${toIndonesianWords(Math.floor(n / 100))} ratus ${toIndonesianWords(n % 100)}`.trim();
  if (n < 2000) return `seribu ${toIndonesianWords(n - 1000)}`.trim();
  if (n < 1_000_000) return `${toIndonesianWords(Math.floor(n / 1000))} ribu ${toIndonesianWords(n % 1000)}`.trim();
  if (n < 1_000_000_000) return `${toIndonesianWords(Math.floor(n / 1_000_000))} juta ${toIndonesianWords(n % 1_000_000)}`.trim();
  return `${n}`;
}

function formatInvoiceDateLong(value?: string): string {
  if (!value) return '-';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return '-';
  return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
}

function resolveInvoiceStartDate(item: {
  start_date?: string | null;
  start?: string | null;
}): string {
  return (item.start_date || item.start || '').toString();
}

function resolveInvoiceTempoDate(item: {
  tempo_date?: string | null;
  tempo?: string | null;
  temp?: string | null;
}): string {
  return (item.tempo_date || item.tempo || item.temp || '').toString();
}

// Paste tanda tangan base64 Anda di sini, contoh: "data:image/png;base64,iVBORw0..."
// Paste base64 tanda tangan di bawah ini (format: data:image/png;base64,....)
const INVOICE_SIGNATURE_BASE64 = "data:image/png;base64,";

export default function VPS() {
  const qc = useQueryClient();
  type VpsInvoiceItem = TTVpsDetailItemDTO & { __periode: string };
  // Filters
  const [open, setOpen] = useState(false);
  const [editItem, setEditItem] = useState<VpsInvoiceItem | null>(null);
  const [openEdit, setOpenEdit] = useState(false);
  const [invoiceDialogOpen, setInvoiceDialogOpen] = useState(false);
  const [invoiceItems, setInvoiceItems] = useState<VpsInvoiceItem[]>([]);
  const [invoiceDialogMode, setInvoiceDialogMode] = useState<'generate' | 'download'>('generate');
  const [selectedInvoiceItems, setSelectedInvoiceItems] = useState<Record<string, VpsInvoiceItem>>({});

  // Filters: period (from/to month), status, and search term
  const currentMonth = useMemo(() => format(new Date(), 'yyyy-MM'), []);
  const [periodFrom, setPeriodFrom] = useState<string>(currentMonth);
  const [periodTo, setPeriodTo] = useState<string>(currentMonth);
  const [tokoFilter, setTokoFilter] = useState<string>('ALL');
  const [statusFilter, setStatusFilter] = useState<'OPEN'|'PROCESS'|'DONE'|'ALL'>('OPEN');
  const [searchTerm, setSearchTerm] = useState<string>('');

  const months = useMemo(() => {
    if (!periodFrom || !periodTo) return [];
    return enumerateMonths(periodFrom, periodTo);
  }, [periodFrom, periodTo]);
  const detailQueries = useQueries({
    queries: months.map((p) => ({
      queryKey: ['tt-vps-details', p],
      queryFn: () => fetchDetailsByPeriode(p),
    })),
    combine: (results) => ({
      data: results.flatMap(r => (Array.isArray(r.data) ? r.data : []) ) as any,
      pending: results.some(r => r.isLoading),
    })
  });

  const { data: subsAll } = useQuery({ queryKey: ['subs-all'], queryFn: () => fetchSubscribers(true) });
  const { data: rekeningInvoiceList = [] } = useQuery({
    queryKey: ['rekening-all-invoice'],
    queryFn: async () => {
      const res = await axiosInstance.get('/master/rekening?all=true');
      return res.data || [];
    },
  });
  const tokoOptions = useMemo(() => {
    const names = Array.from(new Set((subsAll || []).map(s => s.toko))).sort();
    return ['ALL', ...names];
  }, [subsAll]);

  const detailsByToko = useQuery({
    queryKey: ['tt-vps-details-by-toko', tokoFilter],
    queryFn: () => fetchDetailsByToko(tokoFilter),
    enabled: !periodFrom && !periodTo && tokoFilter !== 'ALL'
  });

  const [localItems, setLocalItems] = useState<any[]>([]);
  useEffect(() => {
    // Sync localItems with fetched data
    const docs = months.length > 0 ? ((detailQueries as any).data as any[]) : ((detailsByToko.data as any[]) || []);
    if (!Array.isArray(docs)) return setLocalItems([]);
    const items = docs.map(doc => ({ ...doc, __periode: doc.periode }));
    setLocalItems(items);
  }, [detailQueries, detailsByToko.data, months.length]);

  const combinedItems = useMemo(() => {
    const containsText = (s: string, q: string) => s?.toLowerCase().includes(q.toLowerCase());
    const filtered = localItems.filter((it) => {
      const matchStatus = statusFilter === 'ALL' ? true : it.status === statusFilter;
      const matchToko = tokoFilter === 'ALL' ? true : it.toko === tokoFilter;
      const matchSearch = !searchTerm || containsText(it.toko, searchTerm) || containsText(it.program, searchTerm) || containsText((it as any).daerah, searchTerm);
      return matchStatus && matchToko && matchSearch;
    });
    // Sort by start date ascending, then by toko name ascending
    return filtered.sort((a: any, b: any) => {
      const da = new Date(a?.start || 0).getTime();
      const db = new Date(b?.start || 0).getTime();
      if (da !== db) return da - db;
      const ta = String(a?.toko || '');
      const tb = String(b?.toko || '');
      return ta.localeCompare(tb, 'id-ID', { sensitivity: 'base' });
    });
  }, [localItems, statusFilter, tokoFilter, searchTerm]);

  const itemKey = (item: VpsInvoiceItem) => `${item.__periode}-${item._id}`;
  const isSelectableForBulk = (item: VpsInvoiceItem) => item.status === 'OPEN' && (item.is_active ?? true) !== false;
  const isSelected = (item: VpsInvoiceItem) => !!selectedInvoiceItems[itemKey(item)];

  const visibleSelectableItems = useMemo(
    () => (combinedItems || []).filter((it: VpsInvoiceItem) => isSelectableForBulk(it)),
    [combinedItems]
  );
  const allVisibleSelected = useMemo(
    () => visibleSelectableItems.length > 0 && visibleSelectableItems.every((it: VpsInvoiceItem) => !!selectedInvoiceItems[itemKey(it)]),
    [visibleSelectableItems, selectedInvoiceItems]
  );
  const selectedCount = useMemo(() => Object.keys(selectedInvoiceItems).length, [selectedInvoiceItems]);
  const selectedVisibleItems = useMemo(
    () => (combinedItems || []).filter((it: VpsInvoiceItem) => !!selectedInvoiceItems[itemKey(it)]),
    [combinedItems, selectedInvoiceItems]
  );

  const toggleSelected = (item: VpsInvoiceItem) => {
    if (!isSelectableForBulk(item)) return;
    const key = itemKey(item);
    setSelectedInvoiceItems((prev) => {
      const next = { ...prev };
      if (next[key]) delete next[key];
      else next[key] = item;
      return next;
    });
  };

  const toggleSelectedAllVisible = () => {
    setSelectedInvoiceItems((prev) => {
      const next = { ...prev };
      if (allVisibleSelected) {
        visibleSelectableItems.forEach((it: VpsInvoiceItem) => {
          delete next[itemKey(it)];
        });
      } else {
        visibleSelectableItems.forEach((it: VpsInvoiceItem) => {
          next[itemKey(it)] = it;
        });
      }
      return next;
    });
  };

  const clearSelection = () => setSelectedInvoiceItems({});

  useEffect(() => {
    const visibleKeys = new Set((combinedItems || []).map((it: VpsInvoiceItem) => itemKey(it)));
    setSelectedInvoiceItems((prev) => {
      const next: Record<string, VpsInvoiceItem> = {};
      for (const [k, v] of Object.entries(prev)) {
        if (visibleKeys.has(k)) next[k] = v;
      }
      return next;
    });
  }, [combinedItems]);

  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const toggleExpand = (id: string, periode: string) => {
    setExpanded((prev) => ({ ...prev, [`${periode}-${id}`]: !prev[`${periode}-${id}`] }));
  };

  // Next fiscal caption based on last period in backend
  const { data: lastPeriodData } = useQuery({ queryKey: ['tt-vps-last-period'], queryFn: fetchLastPeriod });
  const nextFiscalLabel = useMemo(() => {
    if (!lastPeriodData) return '';
    const y = parseInt(String(lastPeriodData).slice(0,4), 10);
    if (!y) return '';
    return String(y + 1);
  }, [lastPeriodData]);

  const [genJob, setGenJob] = useState<{ jobId: string; total: number; done: number; label: number; status: 'running'|'done'|'error' } | null>(null);
  const handleStartGenerate = async () => {
    try {
      const res = await startGenerateNextFiscal();
      setGenJob({ jobId: res.jobId, total: res.total || 0, done: 0, label: res.nextFiscalLabel, status: 'running' });
    } catch (e: any) {
      toast.error(e?.response?.data?.message || 'Gagal mulai generate data');
    }
  };
  useEffect(() => {
    if (!genJob || genJob.status !== 'running') return;
    const id = setInterval(async () => {
      try {
        const st = await getGenerateStatus(genJob.jobId);
        setGenJob((prev) => prev ? { ...prev, done: st.done, status: st.status } : prev);
        if (st.status === 'done') {
          clearInterval(id);
          toast.success(`Generate ${st.nextFiscalLabel} berhasil (${st.total} toko)`);
          qc.invalidateQueries({ queryKey: ['tt-vps-details'] });
          qc.invalidateQueries({ queryKey: ['vps-tt-aggregates'] });
        } else if (st.status === 'error') {
          clearInterval(id);
          toast.error(st.error || 'Generate gagal');
        }
      } catch (e: any) {
        clearInterval(id);
        toast.error('Gagal memantau progres generate');
      }
    }, 1000);
    return () => clearInterval(id);
  }, [genJob?.jobId, genJob?.status]);

  const startCreate = () => { setEditItem(null); setOpen(true); };
  const startEdit = (item: VpsInvoiceItem) => { setEditItem(item); setOpenEdit(true); };
  const startGenerateInvoice = (item: VpsInvoiceItem) => {
    setInvoiceDialogMode('generate');
    setInvoiceItems([item]);
    setInvoiceDialogOpen(true);
  };
  const startDownloadInvoice = (item: VpsInvoiceItem) => {
    if (!item.invoice_meta) {
      toast.error('Data invoice belum tersedia untuk item ini.');
      return;
    }
    setInvoiceDialogMode('download');
    setInvoiceItems([item]);
    setInvoiceDialogOpen(true);
  };
  const startGenerateBulkInvoice = () => {
    if (selectedVisibleItems.length === 0) {
      toast.warn('Pilih minimal 1 data OPEN & aktif untuk generate invoice gabungan.');
      return;
    }
    setInvoiceDialogMode('generate');
    setInvoiceItems(selectedVisibleItems);
    setInvoiceDialogOpen(true);
  };

  const delMut = useMutation({
    mutationFn: ({ periode, itemId }: { periode: string; itemId: string }) => deleteTTItem({ periode, itemId }),
    onSuccess: (_data, variables) => {
      toast.success('Data dihapus');
      setLocalItems((prev) => prev.filter((item) => !(item.__periode === variables.periode && item._id === variables.itemId)));
      qc.invalidateQueries({ queryKey: ['tt-vps-details'] });
    },
    onError: (e: any) => toast.error(e?.response?.data?.message || 'Gagal hapus data'),
  });

  const updateActiveMut = useMutation({
    mutationFn: ({ periode, itemId, is_active }: { periode: string; itemId: string; is_active: boolean }) => updateItemActive({ periode, itemId, is_active }),
    onSuccess: (_data, variables) => {
      toast.success(variables.is_active ? 'Data diaktifkan' : 'Data dinonaktifkan');
      setLocalItems((prev) => prev.map((item) =>
        item.__periode === variables.periode && item._id === variables.itemId
          ? { ...item, is_active: variables.is_active }
          : item
      ));
      qc.invalidateQueries({ queryKey: ['tt-vps-details'] });
      qc.invalidateQueries({ queryKey: ['vps-tt-aggregates'] });
    },
    onError: (e: any) => toast.error(e?.response?.data?.message || 'Gagal ubah status aktif'),
  });

  const updateStatusMut = useMutation({
    mutationFn: ({ periode, itemId, status, tanggalLunas }: { periode: string; itemId: string; status: 'OPEN' | 'PROCESS' | 'DONE'; tanggalLunas?: string }) => updateItemStatus({ periode, itemId, status, tanggalLunas }),
    onSuccess: (_data, variables) => {
      toast.success('Status diperbarui');
      setLocalItems((prev) => prev.map((item) =>
        item.__periode === variables.periode && item._id === variables.itemId
          ? { ...item, status: variables.status, tanggalLunas: variables.tanggalLunas ?? item.tanggalLunas }
          : item
      ));
      qc.invalidateQueries({ queryKey: ['tt-vps-details'] });
    },
    onError: (e: any) => toast.error(e?.response?.data?.message || 'Gagal ubah status'),
  });

  const generateInvoiceMut = useMutation({
    mutationFn: (params: {
      periode?: string;
      itemId?: string;
      payload: {
        target_items?: Array<{ periode: string; item_id: string }>;
        customer: { name: string; address: string; phone: string };
        payment_accounts?: Array<{ kode_bank?: string; no_rekening?: string; nama_rekening?: string }>;
        items: Array<{ program_name: string; qty: number; unit_price: number; line_total?: number; start_date?: string; tempo_date?: string }>;
        discount_label?: string;
        discount_percent: number;
        discount_rp: number;
        extra_deduction_rp?: number;
        subtotal: number;
        grand_total: number;
        notes?: string;
        display_date?: string;
      };
    }) => generateInvoiceVps(params),
    onSuccess: (_data, variables) => {
      const affectedKeys = new Set(
        (Array.isArray(_data?.affected_items) && _data.affected_items.length > 0
          ? _data.affected_items
          : variables.periode && variables.itemId
            ? [{ periode: variables.periode, item_id: variables.itemId }]
            : []
        ).map((item) => `${item.periode}::${item.item_id}`)
      );
      setLocalItems((prev) => prev.map((item) =>
        affectedKeys.has(`${item.__periode}::${item._id}`)
          ? { ...item, status: 'PROCESS' }
          : item
      ));
      qc.invalidateQueries({ queryKey: ['tt-vps-details'] });
      qc.invalidateQueries({ queryKey: ['vps-tt-aggregates'] });
    },
  });

  // Summary for current table view
  const summary = useMemo(() => {
    const rows = Array.isArray(combinedItems) ? combinedItems : [];
    const activeRows = rows.filter((it: any) => (it?.is_active ?? true) !== false);
    const total = activeRows.reduce((sum: number, it: any) => sum + (Number(it?.total_harga) || 0), 0);
    const uniqueToko = new Set(activeRows.map((r: any) => r.toko)).size;
    return { total, uniqueToko, count: rows.length };
  }, [combinedItems]);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">VPS Subscription</h2>
        <div className="flex gap-2">
          <Button
            onClick={startCreate}
            className="bg-gradient-to-r from-blue-600 to-indigo-700 hover:from-blue-700 hover:to-indigo-800 text-white font-semibold px-6 py-3 rounded-lg shadow-lg hover:shadow-xl transition-all duration-200 transform hover:scale-[1.02]"
          >
            Tambah VPS
          </Button>
          <ConfirmAction
            title="Generate Data?"
            description={nextFiscalLabel ? `Anda yakin ingin generate data VPS untuk periode ${nextFiscalLabel}?` : 'Menentukan tahun...'}
            actionText="Ya, Generate"
            onConfirm={handleStartGenerate}
          >
            <Button
              disabled={(genJob?.status === 'running') || !nextFiscalLabel}
              className="bg-gradient-to-r from-purple-600 to-fuchsia-700 hover:from-purple-700 hover:to-fuchsia-800 text-white font-semibold px-6 py-3 rounded-lg shadow-lg hover:shadow-xl transition-all duration-200 transform hover:scale-[1.02]"
              title={nextFiscalLabel ? `Generate Data ${nextFiscalLabel}` : 'Menentukan tahun...'}
            >
              {(genJob?.status === 'running') ? (
                <span className="inline-flex items-center gap-2">
                  <span className="h-4 w-4 border-2 border-white/70 border-t-transparent rounded-full animate-spin"></span>
                  <span>Generate...</span>
                </span>
              ) : (
                nextFiscalLabel ? `Generate Data ${nextFiscalLabel}` : 'Generate Data'
              )}
            </Button>
          </ConfirmAction>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white/50 rounded-lg p-4 border-2 border-dashed border-blue-200">
        <div className="grid grid-cols-1 md:grid-cols-6 gap-3 items-end">
          <div>
            <Label>Toko</Label>
            <Select value={tokoFilter} onValueChange={(v) => {
              // Jika beralih ke ALL sementara periode kosong, paksa isi periode saat ini
              if (v === 'ALL' && (!periodFrom || !periodTo)) {
                toast.warn('Toko = ALL, periode wajib diisi');
                setPeriodFrom(currentMonth);
                setPeriodTo(currentMonth);
              }
              setTokoFilter(v);
            }}>
              <SelectTrigger className="w-full"><SelectValue /></SelectTrigger>
              <SelectContent>
                {tokoOptions.map((name) => (
                  <SelectItem key={name} value={name}>{name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label>Periode Dari</Label>
            <Input
              type="month"
              value={periodFrom}
              onChange={(e) => {
                const v = e.target.value;
                if (tokoFilter === 'ALL' && !v) {
                  toast.warn('Toko = ALL, periode wajib diisi');
                  return;
                }
                setPeriodFrom(v);
              }}
            />
          </div>
          <div>
            <Label>Periode Sampai</Label>
            <Input
              type="month"
              value={periodTo}
              onChange={(e) => {
                const v = e.target.value;
                if (tokoFilter === 'ALL' && !v) {
                  toast.warn('Toko = ALL, periode wajib diisi');
                  return;
                }
                setPeriodTo(v);
              }}
            />
          </div>
          <div>
            <Label>Status</Label>
            <Select value={statusFilter} onValueChange={(v) => setStatusFilter(v as any)}>
              <SelectTrigger className="w-full"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="OPEN">OPEN</SelectItem>
                <SelectItem value="PROCESS">PROCESS</SelectItem>
                <SelectItem value="DONE">DONE</SelectItem>
                <SelectItem value="ALL">ALL</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="md:col-span-2">
            <Label>Search Data</Label>
            <Input
              placeholder="Cari berdasarkan toko/program/daerah..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="border-2 border-gray-200 focus:border-blue-400 focus:ring-2 focus:ring-blue-100 transition-all duration-200"
            />
          </div>
        </div>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle>Daftar VPS</CardTitle>
            <div className="flex items-center gap-3">
              <Button
                type="button"
                onClick={startGenerateBulkInvoice}
                disabled={selectedCount === 0 || generateInvoiceMut.isPending}
                className="bg-gradient-to-r from-blue-500 to-indigo-600 hover:from-blue-600 hover:to-indigo-700 text-white"
              >
                Generate Invoice Terpilih ({selectedCount})
              </Button>
              <div className="text-sm text-gray-700 flex items-center gap-4">
                <span className="font-semibold">Total: {currency(summary.total)}</span>
                <span>Subscriber: <span className="font-semibold">{summary.uniqueToko}</span></span>
              </div>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {(detailQueries as any).pending ? (
            <div>Loading...</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead>
                  <tr className="text-left border-b">
                    <th className="py-2 pr-4 w-10">
                      <input
                        type="checkbox"
                        checked={allVisibleSelected}
                        onChange={toggleSelectedAllVisible}
                        aria-label="Pilih semua item OPEN aktif"
                        className="h-4 w-4"
                      />
                    </th>
                    <th className="py-2 pr-4"></th>
                    <th className="py-2 pr-4">Toko</th>
                    <th className="py-2 pr-4">Start Date</th>
                    <th className="py-2 pr-4">Bulan</th>
                    <th className="py-2 pr-4">Tempo</th>
                    <th className="py-2 pr-4">Harga/Bln</th>
                    <th className="py-2 pr-4">Total</th>
                    <th className="py-2 pr-4">Status</th>
                    <th className="py-2 pr-4">Aksi</th>
                  </tr>
                </thead>
                <tbody>
                  {combinedItems?.map((item: VpsInvoiceItem) => (
                    <Fragment key={`${item.__periode}-${item._id}`}>
                    <tr key={`${item.__periode}-${item._id}`} className="border-b">
                      <td className="py-2 pr-4">
                        <input
                          type="checkbox"
                          checked={isSelected(item)}
                          disabled={!isSelectableForBulk(item)}
                          onChange={() => toggleSelected(item)}
                          title={!isSelectableForBulk(item) ? 'Hanya status OPEN dan aktif yang bisa dipilih' : 'Pilih untuk invoice gabungan'}
                          className="h-4 w-4"
                        />
                      </td>
                      <td className="py-2 pr-4">
                        <Button variant="ghost" size="sm" onClick={() => toggleExpand(item._id, item.__periode)} aria-label="Expand">
                          {expanded[`${item.__periode}-${item._id}`] ? '▾' : '▸'}
                        </Button>
                      </td>
                      <td className="py-2 pr-4">{item.toko}</td>
                      <td className="py-2 pr-4">{format(new Date(item.start), 'dd MMM yyyy')}</td>
                      <td className="py-2 pr-4">{item.bulan}</td>
                      <td className="py-2 pr-4">{format(new Date(item.tempo), 'dd MMM yyyy')}</td>
                      <td className="py-2 pr-4">{currency(item.harga)}</td>
                      <td className="py-2 pr-4">{currency(item.total_harga)}</td>
                      <td className="py-2 pr-4">
                        {item.status === 'DONE' ? (
                          <span className="inline-flex items-center rounded-full bg-green-100 text-green-700 px-2 py-0.5 text-xs font-medium">DONE</span>
                        ) : item.status === 'PROCESS' ? (
                          <span className="inline-flex items-center rounded-full bg-yellow-100 text-yellow-700 px-2 py-0.5 text-xs font-medium">PROCESS</span>
                        ) : (
                          <span className="inline-flex items-center rounded-full bg-gray-200 text-gray-700 px-2 py-0.5 text-xs font-medium">OPEN</span>
                        )}
                        {(item.is_active ?? true) === false && (
                          <span className="inline-flex items-center rounded-full bg-red-100 text-red-700 px-2 py-0.5 text-xs font-medium ml-2">Nonaktif</span>
                        )}
                      </td>
                      <td className="py-2 pr-4 flex gap-2">
                        {item.status === 'OPEN' && (
                          <Button
                            size="icon"
                            aria-label="Generate invoice"
                            title="Generate invoice"
                            className="rounded-full bg-gradient-to-r from-blue-500 to-indigo-600 hover:from-blue-600 hover:to-indigo-700 text-white shadow-md hover:shadow-lg border border-white/10 transition-transform hover:scale-105"
                            disabled={generateInvoiceMut.isPending || ((item.is_active ?? true) === false)}
                            onClick={() => startGenerateInvoice(item)}
                          >
                            <FileCheck className="h-5 w-5" />
                          </Button>
                        )}
                        {item.status === 'OPEN' && (
                          (item.is_active ?? true) !== false ? (
                            <ConfirmAction
                              title="Nonaktifkan VPS?"
                              description="Data akan dinonaktifkan untuk periode ini. Tidak bisa diproses invoice/pelunasan hingga diaktifkan kembali."
                              actionText="Ya, Nonaktifkan"
                              preview={<VpsItemPreview item={item} />}
                              onConfirm={() => updateActiveMut.mutate({ periode: item.__periode, itemId: item._id, is_active: false })}
                            >
                              <Button
                                size="icon"
                                aria-label="Nonaktifkan"
                                title="Nonaktifkan data"
                                className="rounded-full bg-gradient-to-r from-rose-500 to-red-600 hover:from-rose-600 hover:to-red-700 text-white shadow-md hover:shadow-lg border border-white/10 transition-transform hover:scale-105"
                                disabled={updateActiveMut.isPending}
                              >
                                <span className="font-bold">Ø</span>
                              </Button>
                            </ConfirmAction>
                          ) : (
                            <ConfirmAction
                              title="Aktifkan kembali?"
                              description="Data akan diaktifkan kembali dan kembali dihitung dalam estimasi."
                              actionText="Ya, Aktifkan"
                              preview={<VpsItemPreview item={item} />}
                              onConfirm={() => updateActiveMut.mutate({ periode: item.__periode, itemId: item._id, is_active: true })}
                            >
                              <Button
                                size="icon"
                                aria-label="Aktifkan kembali"
                                title="Aktifkan kembali"
                                className="rounded-full bg-gradient-to-r from-teal-500 to-emerald-600 hover:from-teal-600 hover:to-emerald-700 text-white shadow-md hover:shadow-lg border border-white/10 transition-transform hover:scale-105"
                                disabled={updateActiveMut.isPending}
                              >
                                <span className="font-bold">↺</span>
                              </Button>
                            </ConfirmAction>
                          )
                        )}
                        {item.status === 'PROCESS' && (
                          <>
                            <Button
                              size="icon"
                              aria-label="Download invoice"
                              title="Download ulang invoice"
                              className="rounded-full bg-gradient-to-r from-sky-500 to-blue-600 hover:from-sky-600 hover:to-blue-700 text-white shadow-md hover:shadow-lg border border-white/10 transition-transform hover:scale-105"
                              onClick={() => startDownloadInvoice(item)}
                            >
                              <FileDown className="h-5 w-5" />
                            </Button>
                            <ConfirmAction
                              title="Selesaikan VPS?"
                              description="Status akan diubah menjadi DONE. Pilih tanggal lunas:"
                              actionText="Ya, Selesaikan"
                              showDate
                              preview={<VpsItemPreview item={item} />}
                              onConfirm={(tanggalLunas?: string) => updateStatusMut.mutate({ periode: item.__periode, itemId: item._id, status: 'DONE', tanggalLunas })}
                            >
                              <Button
                                size="icon"
                                aria-label="Tandai selesai"
                                title="Tandai selesai"
                                className="rounded-full bg-gradient-to-r from-emerald-500 to-green-600 hover:from-emerald-600 hover:to-green-700 text-white shadow-md hover:shadow-lg border border-white/10 transition-transform hover:scale-105"
                                disabled={updateStatusMut.isPending}
                              >
                                <CheckCircle2 className="h-5 w-5" />
                              </Button>
                            </ConfirmAction>
                            <ConfirmAction
                              title="Batalkan Proses?"
                              description="Status akan dikembalikan ke OPEN. Data akan bisa diedit dan dihapus kembali."
                              actionText="Ya, Batalkan"
                              onConfirm={() => updateStatusMut.mutate({ periode: item.__periode, itemId: item._id, status: 'OPEN' })}
                            >
                              <Button
                                size="icon"
                                aria-label="Batalkan proses"
                                title="Batalkan proses"
                                className="rounded-full bg-gradient-to-r from-orange-400 to-yellow-500 hover:from-orange-500 hover:to-yellow-600 text-white shadow-md hover:shadow-lg border border-white/10 transition-transform hover:scale-105"
                                disabled={updateStatusMut.isPending}
                              >
                                <RotateCcw className="h-5 w-5" />
                              </Button>
                            </ConfirmAction>
                          </>
                        )}
                        {item.status === 'DONE' && (
                          <>
                            <Button
                              size="icon"
                              aria-label="Download invoice"
                              title="Download ulang invoice"
                              className="rounded-full bg-gradient-to-r from-sky-500 to-blue-600 hover:from-sky-600 hover:to-blue-700 text-white shadow-md hover:shadow-lg border border-white/10 transition-transform hover:scale-105"
                              onClick={() => startDownloadInvoice(item)}
                            >
                              <FileDown className="h-5 w-5" />
                            </Button>
                            <ConfirmAction
                              title="Batal Pelunasan?"
                              description="Status akan dikembalikan ke PROCESS dan realisasi di periode tgl lunas akan dikurangi."
                              actionText="Ya, Batalkan"
                              onConfirm={() => updateStatusMut.mutate({ periode: item.__periode, itemId: item._id, status: 'PROCESS' })}
                            >
                              <Button
                                size="icon"
                                aria-label="Batal pelunasan"
                                title="Batal pelunasan"
                                className="rounded-full bg-gradient-to-r from-orange-500 to-amber-600 hover:from-orange-600 hover:to-amber-700 text-white shadow-md hover:shadow-lg border border-white/10 transition-transform hover:scale-105"
                                disabled={updateStatusMut.isPending}
                              >
                                <RotateCcw className="h-5 w-5" />
                              </Button>
                            </ConfirmAction>
                          </>
                        )}
                        <Button
                          size="icon"
                          variant="secondary"
                          onClick={() => item.status === 'OPEN' ? startEdit(item) : undefined}
                          disabled={item.status !== 'OPEN'}
                          title={item.status !== 'OPEN' ? 'Edit tersedia hanya untuk status OPEN' : 'Edit'}
                        >
                          <Pencil className="h-4 w-4" />
                        </Button>
                        {item.status === 'OPEN' ? (
                          <ConfirmAction
                            title="Hapus VPS?"
                            description="Data akan dihapus permanen. Lanjutkan?"
                            actionText="Ya, Hapus"
                            onConfirm={() => delMut.mutate({ periode: item.__periode, itemId: item._id })}
                          >
                            <Button size="icon" variant="destructive"><Trash2 className="h-4 w-4" /></Button>
                          </ConfirmAction>
                        ) : (
                          <Button
                            size="icon"
                            variant="destructive"
                            disabled
                            title="Hapus tersedia hanya untuk status OPEN"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        )}
                      </td>
                    </tr>
                    {expanded[`${item.__periode}-${item._id}`] && (
                      <tr className="bg-slate-50">
                        <td colSpan={10} className="py-2 px-4">
                          <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                            <div>
                              <div className="text-xs text-slate-500">Program</div>
                              <div className="text-sm font-medium">{item.program}</div>
                            </div>
                            <div>
                              <div className="text-xs text-slate-500">Daerah</div>
                              <div className="text-sm font-medium">{item.daerah}</div>
                            </div>
                            <div>
                              <div className="text-xs text-slate-500">Diskon (%)</div>
                              <div className="text-sm font-medium">{item.diskon_percent || 0}%</div>
                            </div>
                            <div>
                              <div className="text-xs text-slate-500">Diskon (Rp)</div>
                              <div className="text-sm font-medium">{currency(item.diskon)}</div>
                            </div>
                            <div>
                              <div className="text-xs text-slate-500">Tanggal Lunas</div>
                              <div className="text-sm font-medium">
                                {item.tgl_lunas ? format(new Date(item.tgl_lunas), 'dd MMM yyyy') : <span className="text-slate-400">-</span>}
                              </div>
                            </div>
                            <div>
                              <div className="text-xs text-slate-500">Keterangan</div>
                              <div className="text-sm font-medium">{item?.keterangan || '-'}</div>
                            </div>
                          </div>
                        </td>
                      </tr>
                    )}
                    </Fragment>
                  ))}
                  {!combinedItems?.length && (
                    <tr><td className="py-4 text-slate-500" colSpan={10}>Belum ada data</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>

      {genJob?.status === 'running' && (
        <div className="fixed inset-0 z-50 bg-black/30 backdrop-blur-sm flex items-center justify-center">
          <div className="bg-white rounded-lg p-5 shadow-xl w-[460px]">
            <div className="mb-3 font-semibold">Generate data {genJob?.label || nextFiscalLabel || ''}...</div>
            <Progress value={genJob?.total ? Math.round(((genJob?.done || 0) / genJob.total) * 100) : 0} />
            <div className="mt-2 text-sm text-gray-600 flex justify-between">
              <span>{genJob?.done || 0} / {genJob?.total || 0} toko</span>
              <span>{genJob?.total ? Math.round(((genJob?.done || 0) / genJob.total) * 100) : 0}%</span>
            </div>
            <div className="mt-1 text-xs text-gray-400">Mohon tunggu, proses bisa memakan waktu.</div>
          </div>
        </div>
      )}

      <InvoiceGenerateDialog
        open={invoiceDialogOpen}
        onOpenChange={(v) => {
          setInvoiceDialogOpen(v);
          if (!v) setInvoiceItems([]);
        }}
        mode={invoiceDialogMode}
        items={invoiceItems}
        subscribers={subsAll || []}
        paymentAccounts={rekeningInvoiceList || []}
        onAutoSavePhone={async ({ kode, nomor_telepon }) => {
          await updateSubscriberPhoneByKode({ kode, nomor_telepon });
        }}
        onGenerate={async (payload) => {
          if (!invoiceItems.length) throw new Error('Item invoice tidak valid.');
          const firstItem = invoiceItems[0];
          const targetItems = invoiceItems.map((item) => ({
            periode: item.__periode,
            item_id: item._id,
          }));

          if (invoiceDialogMode === 'download') {
            const meta = firstItem.invoice_meta;
            if (!meta) throw new Error('Snapshot invoice tidak ditemukan.');
            const displayDate = payload.display_date || meta.display_date || new Date().toISOString().slice(0, 10);
            return {
              invoice_number: String(meta.invoice_number || generateLocalInvoiceNumber(displayDate)),
              generated_at: String(meta.generated_at || new Date().toISOString()),
              generated_by: String(meta.generated_by || 'RE-DOWNLOAD'),
              sender: meta.sender || {
                name: 'PT. GRAHA INTEGRA APLIKASI',
                address: '',
                phone: '',
              },
              customer: {
                name: payload.customer.name,
                address: payload.customer.address || '',
                phone: payload.customer.phone || '',
              },
              payment_accounts: Array.isArray(payload.payment_accounts)
                ? payload.payment_accounts.map((acc) => ({
                    kode_bank: String(acc?.kode_bank || '').trim(),
                    no_rekening: String(acc?.no_rekening || '').trim(),
                    nama_rekening: String(acc?.nama_rekening || '').trim(),
                  })).filter((acc) => acc.no_rekening)
                : (Array.isArray(meta.payment_accounts) ? meta.payment_accounts : []),
              items: payload.items.map((it) => ({
                program_name: it.program_name,
                qty: Number(it.qty) || 0,
                unit_price: Number(it.unit_price) || 0,
                line_total: Number(it.line_total ?? (Number(it.qty) || 0) * (Number(it.unit_price) || 0)),
                start_date: resolveInvoiceStartDate(it),
                tempo_date: resolveInvoiceTempoDate(it),
              })),
              subtotal: Number(payload.subtotal) || 0,
              discount_label: String(payload.discount_label || meta.discount_label || 'DISC').trim() || 'DISC',
              discount_percent: Number(payload.discount_percent) || 0,
              discount_rp: Number(payload.discount_rp) || 0,
              extra_deduction_rp: Number(payload.extra_deduction_rp) || 0,
              grand_total: Number(payload.grand_total) || 0,
              notes: payload.notes || '',
              display_date: displayDate,
            };
          }

          if (VPS_INVOICE_PRINT_ONLY) {
            const displayDate = payload.display_date || new Date().toISOString().slice(0, 10);
            return {
              invoice_number: generateLocalInvoiceNumber(displayDate),
              generated_at: new Date().toISOString(),
              generated_by: 'DEBUG_PRINT_ONLY',
              sender: {
                name: 'PT. GRAHA INTEGRA APLIKASI',
                address: '',
                phone: '',
              },
              customer: {
                name: payload.customer.name,
                address: payload.customer.address || '',
                phone: payload.customer.phone || '',
              },
              payment_accounts: Array.isArray(payload.payment_accounts)
                ? payload.payment_accounts.map((acc) => ({
                    kode_bank: String(acc?.kode_bank || '').trim(),
                    no_rekening: String(acc?.no_rekening || '').trim(),
                    nama_rekening: String(acc?.nama_rekening || '').trim(),
                  })).filter((acc) => acc.no_rekening)
                : [],
              items: payload.items.map((it) => ({
                program_name: it.program_name,
                qty: Number(it.qty) || 0,
                unit_price: Number(it.unit_price) || 0,
                line_total: Number(it.line_total ?? (Number(it.qty) || 0) * (Number(it.unit_price) || 0)),
                start_date: resolveInvoiceStartDate(it),
                tempo_date: resolveInvoiceTempoDate(it),
              })),
              subtotal: Number(payload.subtotal) || 0,
              discount_label: String(payload.discount_label || 'DISC').trim() || 'DISC',
              discount_percent: Number(payload.discount_percent) || 0,
              discount_rp: Number(payload.discount_rp) || 0,
              extra_deduction_rp: Number(payload.extra_deduction_rp) || 0,
              grand_total: Number(payload.grand_total) || 0,
              notes: payload.notes || '',
              display_date: displayDate,
            };
          }

          const resp = await generateInvoiceMut.mutateAsync({
            periode: invoiceItems.length === 1 ? firstItem.__periode : undefined,
            itemId: invoiceItems.length === 1 ? firstItem._id : undefined,
            payload: {
              ...payload,
              payment_accounts: Array.isArray(payload.payment_accounts)
                ? payload.payment_accounts.map((acc) => ({
                    kode_bank: String(acc?.kode_bank || '').trim(),
                    no_rekening: String(acc?.no_rekening || '').trim(),
                    nama_rekening: String(acc?.nama_rekening || '').trim(),
                  })).filter((acc) => acc.no_rekening)
                : [],
              target_items: targetItems,
            },
          });
          return resp.invoice;
        }}
      />

      <VpsFormDialog
        open={open}
        onOpenChange={setOpen}
        editItem={null}
          onSuccess={() => { qc.invalidateQueries({ queryKey: ['tt-vps-details'] }); }}
      />
      <TTVpsEditDialog
        open={openEdit}
        onOpenChange={setOpenEdit}
        item={editItem}
        onSuccess={() => { setOpenEdit(false); qc.invalidateQueries({ queryKey: ['tt-vps-details'] }); }}
      />
    </div>
  );
}

function VpsFormDialog({ open, onOpenChange, editItem, onSuccess }: { open: boolean; onOpenChange: (v: boolean) => void; editItem: null; onSuccess: () => void }) {
  const { data: subs } = useQuery({ queryKey: ['vps-available-subs'], queryFn: fetchAvailableSubscribers, enabled: !editItem });
  const qc = useQueryClient();
  const createMut = useMutation({
    mutationFn: (payload: { subscriberId?: string; startDate: string; months: number; discount?: number; discountPercent?: number; keterangan?: string }) =>
      createSchedule({ subscriber_id: payload.subscriberId, start: payload.startDate, bulan: payload.months, diskon: payload.discount, diskon_percent: payload.discountPercent, keterangan: payload.keterangan }),
    onSuccess: () => {
      toast.success('Data disimpan');
      // Tetap buka form; reset field agar siap input berikutnya
      setSubscriberId('');
      setStartDate('');
      setMonthsText('');
      setDiscountPercentText('');
      onSuccess();
      qc.invalidateQueries({ queryKey: ['vps-available-subs'] });
      qc.invalidateQueries({ queryKey: ['tt-vps-details'] });
    },
    onError: (e: any) => toast.error(e?.response?.data?.message || 'Gagal simpan data'),
  });
  // Update/edit for TT items will be added after edit semantics are confirmed

  const [subscriberId, setSubscriberId] = useState<string>('');
  const selectedSub = useMemo(() => subs?.find(s => s._id === subscriberId), [subs, subscriberId]);
  const pricePerMonth = selectedSub?.biaya || 0;

  const [startDate, setStartDate] = useState<string>('');
  const [monthsText, setMonthsText] = useState<string>('');
  const [discountPercentText, setDiscountPercentText] = useState<string>('');
  const [keterangan, setKeterangan] = useState<string>('');

  useEffect(() => {
    if (!open) {
      setSubscriberId('');
      setStartDate('');
      setMonthsText('');
      setDiscountPercentText('');
      setKeterangan('');
    }
  }, [open]);

  // Prefill values when editing and dialog opens
  // No edit prefill for TT yet

  const months = useMemo(() => {
    const digits = (monthsText || '').replace(/[^0-9]/g, '');
    if (!digits) return 0;
    return parseInt(digits, 10);
  }, [monthsText]);

  const dueDate = useMemo(() => {
    if (!startDate || !months || months <= 0) return '';
    const d = new Date(startDate);
    // next period start = startDate + months months
    const next = new Date(d);
    const day = next.getDate();
    next.setMonth(next.getMonth() + months);
    if (next.getDate() < day) {
      next.setDate(0);
    }
    // due date = next start - 1 day
    const due = new Date(next);
    due.setDate(due.getDate() - 1);
    return due.toISOString().slice(0,10);
  }, [startDate, months]);

  const gross = (pricePerMonth || 0) * (months || 0);
  const discountPercent = (() => {
    const digits = (discountPercentText || '').replace(/[^0-9]/g, '');
    if (!digits) return 0;
    const p = parseInt(digits, 10);
    return Math.max(0, Math.min(100, p));
  })();
  const discountRp = Math.floor(gross * discountPercent / 100);
  const net = Math.max(0, gross - discountRp);

  const handleSubmit = () => {
    if (!startDate || !months || months <= 0) return toast.error('Lengkapi form: jumlah bulan harus diisi (> 0)');
    if (!subscriberId) return toast.error('Pilih toko terlebih dahulu');
    createMut.mutate({ subscriberId, startDate, months, discount: discountRp, discountPercent, keterangan });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{editItem ? 'Edit VPS' : 'Tambah VPS'}</DialogTitle>
        </DialogHeader>

        {!editItem ? (
          <div className="space-y-2">
            <Label>Toko</Label>
            <Combobox
              options={subs?.map(s => ({ value: s._id, label: `${s.toko} — ${currency(s.biaya)}`, extra: s })) || []}
              value={subscriberId}
              onChange={setSubscriberId}
              placeholder="Pilih Toko"
              renderOption={(opt, active) => (
                <span className={active ? 'font-semibold' : ''}>{opt.label}</span>
              )}
            />
          </div>
        ) : null}

        {selectedSub ? (
          <div className="space-y-2">
            <Label>Program</Label>
            <Input value={selectedSub.program} readOnly />
          </div>
        ) : null}

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-1">
            <Label>Harga/Bln</Label>
            <Input value={currency(pricePerMonth)} readOnly />
          </div>
          <div className="space-y-1">
            <Label>Start Date</Label>
            <Input
              type="date"
              value={startDate}
              onChange={e => setStartDate(e.target.value)}
            />
          </div>
          <div className="space-y-1">
            <Label>Jumlah Bulan</Label>
            <Input
              type="text"
              inputMode="numeric"
              placeholder="0"
              value={monthsText}
              onChange={e => {
                const raw = e.target.value;
                const digits = raw.replace(/[^0-9]/g, '');
                // remove leading zeros except keep single zero if that's all
                const normalized = digits.replace(/^0+(?=\d)/, '');
                setMonthsText(normalized);
              }}
            />
          </div>
          <div className="space-y-1">
            <Label>Tanggal Tempo</Label>
            <Input value={dueDate ? format(new Date(dueDate), 'dd MMM yyyy') : ''} readOnly />
          </div>
          <div className="space-y-1">
            <Label>Jumlah Harga</Label>
            <Input value={currency(gross)} readOnly />
          </div>
          <div className="space-y-1">
            <Label>Diskon (%)</Label>
            <Input
              type="text"
              inputMode="numeric"
              placeholder="0"
              value={discountPercentText}
              onChange={e => {
                const raw = e.target.value;
                const digits = raw.replace(/[^0-9]/g, '').replace(/^0+(?=\d)/, '');
                setDiscountPercentText(digits);
              }}
            />
          </div>
          <div className="space-y-1">
            <Label>Diskon (Rp)</Label>
            <Input value={currency(discountRp)} readOnly />
          </div>
          <div className="space-y-1 col-span-2">
            <Label>Total Harga</Label>
            <Input value={currency(net)} readOnly />
          </div>
          <div className="space-y-1 col-span-2">
            <Label>Keterangan</Label>
            <Input value={keterangan} onChange={e => setKeterangan((e.target.value || '').toUpperCase())} placeholder="Keterangan tambahan..." />
          </div>
        </div>

        <div className="flex justify-end gap-2 pt-2">
          <Button variant="secondary" onClick={() => onOpenChange(false)}>Batal</Button>
          <Button
            onClick={handleSubmit}
            disabled={createMut.isPending || months <= 0}
            className="bg-gradient-to-r from-blue-600 to-indigo-700 hover:from-blue-700 hover:to-indigo-800 text-white font-semibold px-6 py-3 rounded-lg shadow-lg hover:shadow-xl transition-all duration-200 transform hover:scale-[1.02]"
          >
            Tambah
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function TTVpsEditDialog({ open, onOpenChange, item, onSuccess }: { open: boolean; onOpenChange: (v: boolean) => void; item: (TTVpsDetailItemDTO & { __periode: string }) | null; onSuccess: () => void }) {
  const qc = useQueryClient();
  const [startDate, setStartDate] = useState<string>('');
  const [monthsText, setMonthsText] = useState<string>('');
  const [harga, setHarga] = useState<number>(0);
  const [diskonPercentText, setDiskonPercentText] = useState<string>('');
  const [keterangan, setKeterangan] = useState<string>('');

  useEffect(() => {
    if (open && item) {
      setStartDate(item.start);
      setMonthsText(String(item.bulan));
      setHarga(item.harga);
      const base = item.harga * item.bulan;
      const pct = base > 0 ? Math.round((item.diskon / base) * 100) : 0;
      setDiskonPercentText(String(pct));
      setKeterangan(((item as any).keterangan || '').toUpperCase());
    }
    if (!open) {
      setStartDate(''); setMonthsText(''); setHarga(0); setDiskonPercentText('');
      setKeterangan('');
    }
  }, [open, item]);

  const months = useMemo(() => {
    const digits = (monthsText || '').replace(/[^0-9]/g, '');
    if (!digits) return 0;
    return parseInt(digits, 10);
  }, [monthsText]);

  const tempo = useMemo(() => {
    if (!startDate || !months) return '';
    const s = new Date(startDate + 'T00:00:00.000Z');
    const next = new Date(s);
    const day = next.getUTCDate();
    next.setUTCMonth(next.getUTCMonth() + months);
    if (next.getUTCDate() < day) next.setUTCDate(0);
    const due = new Date(next);
    due.setUTCDate(due.getUTCDate() - 1);
    return due.toISOString().slice(0,10);
  }, [startDate, months]);

  const jumlah = (harga || 0) * (months || 0);
  const diskonPercent = (() => {
    const digits = (diskonPercentText || '').replace(/[^0-9]/g, '');
    if (!digits) return 0;
    const p = parseInt(digits, 10);
    return Math.max(0, Math.min(100, p));
  })();
  const diskonRp = Math.floor(jumlah * diskonPercent / 100);
  const total = Math.max(0, jumlah - diskonRp);

  const updateMut = useMutation({
    mutationFn: () => updateTTItem({ periode: item!.__periode, itemId: item!._id, start: startDate, bulan: months, harga, diskon: diskonRp, diskon_percent: diskonPercent, keterangan }),
    onSuccess: () => { toast.success('Data diupdate'); onSuccess(); },
    onError: (e: any) => toast.error(e?.response?.data?.message || 'Gagal update data'),
  });

  const handleSubmit = () => {
    if (!item) return;
    if (!startDate || !months || months <= 0) return toast.error('Lengkapi form (bulan > 0)');
    if (startDate.slice(0,7) !== item.__periode) return toast.error('Tanggal start harus tetap di periode yang sama');
    updateMut.mutate();
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Edit Data VPS</DialogTitle>
        </DialogHeader>
        {item ? (
          <div className="space-y-3">
            <div>
              <Label>Toko</Label>
              <div className="p-2 border rounded bg-slate-50">{item.toko}</div>
            </div>
            <div>
              <Label>Program</Label>
              <div className="p-2 border rounded bg-slate-50">{item.program}</div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Start Date</Label>
                <Input
                  type="date"
                  value={startDate}
                  onChange={e => setStartDate(e.target.value)}
                />
                {startDate && (
                  <div className="text-xs text-gray-500 mt-1">
                    Tanggal dipilih: {format(new Date(startDate), 'dd/MM/yyyy')}
                  </div>
                )}
              </div>
              <div>
                <Label>Jumlah Bulan</Label>
                <Input type="text" inputMode="numeric" value={monthsText} onChange={e => setMonthsText(e.target.value.replace(/[^0-9]/g, '').replace(/^0+(?=\d)/, ''))} />
              </div>
              <div>
                <Label>Harga/Bln</Label>
                <CurrencyInput value={harga} onChange={setHarga} />
              </div>
              <div>
                <Label>Tempo</Label>
                <Input value={tempo ? format(new Date(tempo), 'dd MMM yyyy') : ''} readOnly />
              </div>
              <div>
                <Label>Jumlah Harga</Label>
                <Input value={currency(jumlah)} readOnly />
              </div>
              <div>
                <Label>Diskon (%)</Label>
                <Input type="text" inputMode="numeric" value={diskonPercentText} onChange={e => setDiskonPercentText(e.target.value.replace(/[^0-9]/g, '').replace(/^0+(?=\d)/, ''))} />
              </div>
              <div>
                <Label>Diskon (Rp)</Label>
                <Input value={currency(diskonRp)} readOnly />
              </div>
              <div className="col-span-2">
                <Label>Total Harga</Label>
                <Input value={currency(total)} readOnly />
              </div>
            </div>
            <div className="space-y-1 col-span-2">
              <Label>Keterangan</Label>
              <Input value={keterangan} onChange={e => setKeterangan((e.target.value || '').toUpperCase())} placeholder="Keterangan..." />
            </div>
          </div>
        ) : null}
        <div className="flex justify-end gap-2 pt-2">
          <Button variant="secondary" onClick={() => onOpenChange(false)}>Batal</Button>
          <Button onClick={handleSubmit} disabled={updateMut.isPending || !item || months <= 0} className="bg-gradient-to-r from-blue-600 to-indigo-700 hover:from-blue-700 hover:to-indigo-800 text-white">Simpan</Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function CurrencyInput({ value, onChange }: { value: number; onChange: (n: number) => void }) {
  const [text, setText] = useState<string>(() => formatCurrencyInput(value));

  useEffect(() => {
    setText(formatCurrencyInput(value));
  }, [value]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.value;
    const num = parseCurrencyInput(raw);
    onChange(num);
    setText(formatCurrencyInput(num));
  };

  const handleFocus = () => {
    // Optionally remove 'Rp' on focus; keep formatted display for consistency
  };

  return (
    <Input value={text} onChange={handleChange} onFocus={handleFocus} inputMode="numeric" />
  );
}

type InvoiceLineInput = {
  id: string;
  program_name: string;
  qty: string;
  unit_price: string;
  store_name: string;
  include_store_suffix: boolean;
  start_date?: string;
  tempo_date?: string;
};

type InvoiceSnapshot = {
  invoice_number: string;
  generated_at: string;
  generated_by: string;
  sender: {
    name: string;
    address: string;
    phone: string;
  };
  customer: {
    name: string;
    address: string;
    phone: string;
  };
  payment_accounts?: Array<{
    kode_bank?: string;
    no_rekening?: string;
    nama_rekening?: string;
  }>;
  items: Array<{
    program_name: string;
    qty: number;
    unit_price: number;
    line_total: number;
    start_date?: string;
    tempo_date?: string;
  }>;
  subtotal: number;
  discount_label?: string;
  discount_percent: number;
  discount_rp: number;
  extra_deduction_rp?: number;
  grand_total: number;
  notes?: string;
  display_date: string;
};

function InvoiceGenerateDialog({
  open,
  onOpenChange,
  mode,
  items,
  subscribers,
  paymentAccounts,
  onAutoSavePhone,
  onGenerate,
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  mode: 'generate' | 'download';
  items: Array<TTVpsDetailItemDTO & { __periode: string }>;
  subscribers: Array<{ kode?: string; toko: string; alamat?: string | null; no_ok?: string | null; nomor_telepon?: string | null }>;
  paymentAccounts: Array<{ kode_bank?: string; no_rekening?: string; nama_rekening?: string }>;
  onAutoSavePhone: (params: { kode: string; nomor_telepon: string }) => Promise<unknown>;
  onGenerate: (payload: {
    customer: { name: string; address: string; phone: string };
    payment_accounts?: Array<{ kode_bank?: string; no_rekening?: string; nama_rekening?: string }>;
    items: Array<{ program_name: string; qty: number; unit_price: number; line_total?: number; start_date?: string; tempo_date?: string }>;
    discount_label?: string;
    discount_percent: number;
    discount_rp: number;
    extra_deduction_rp?: number;
    subtotal: number;
    grand_total: number;
    notes?: string;
    display_date?: string;
  }) => Promise<InvoiceSnapshot>;
}) {
  const templateRef = useRef<HTMLDivElement | null>(null);
  const [customerName, setCustomerName] = useState('');
  const [customerAddress, setCustomerAddress] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [subscriberKode, setSubscriberKode] = useState('');
  const [initialPhone, setInitialPhone] = useState('');
  const [displayDate, setDisplayDate] = useState('');
  const [notes, setNotes] = useState('');
  const [lines, setLines] = useState<InvoiceLineInput[]>([]);
  const [discountPercentText, setDiscountPercentText] = useState('0');
  const [discountRpText, setDiscountRpText] = useState('0');
  const [discountLabelText, setDiscountLabelText] = useState('DISC');
  const [extraDeductionRpText, setExtraDeductionRpText] = useState('0');
  const [lastDiscountEdit, setLastDiscountEdit] = useState<'percent' | 'rp'>('percent');
  const [creating, setCreating] = useState(false);
  const [pdfSnapshot, setPdfSnapshot] = useState<InvoiceSnapshot | null>(null);
  const [selectedPaymentAccountKeys, setSelectedPaymentAccountKeys] = useState<string[]>([]);
  const [paymentAccountPicker, setPaymentAccountPicker] = useState<string>('');

  const getPaymentAccountKey = (acc: { _id?: string; kode_bank?: string; no_rekening?: string }, idx: number) =>
    acc?._id || `${acc?.kode_bank || '-'}-${acc?.no_rekening || '-'}-${idx}`;
  const getPaymentAccountLookupKey = (acc: { kode_bank?: string; no_rekening?: string }) =>
    `${String(acc?.kode_bank || '').trim()}::${String(acc?.no_rekening || '').trim()}`;

  useEffect(() => {
    if (!open || !items.length) return;
    const firstItem = items[0];
    const sub = subscribers.find((s) => (s.toko || '').trim() === (firstItem.toko || '').trim());
    const meta = (firstItem as any)?.invoice_meta;
    const isDownloadMode = mode === 'download' && !!meta;
    setCustomerName(isDownloadMode ? String(meta.customer?.name || firstItem.toko || '') : (firstItem.toko || ''));
    setCustomerAddress(isDownloadMode ? String(meta.customer?.address || '') : (sub?.alamat || '').toString());
    const defaultPhone = isDownloadMode
      ? String(meta.customer?.phone || '')
      : (sub?.nomor_telepon || sub?.no_ok || '').toString();
    setCustomerPhone(defaultPhone);
    setInitialPhone(defaultPhone);
    setSubscriberKode((sub?.kode || '').toString());
    setDisplayDate(isDownloadMode ? String(meta.display_date || new Date().toISOString().slice(0, 10)) : new Date().toISOString().slice(0, 10));
    setNotes(
      isDownloadMode
        ? String(meta.notes || '')
        : ((firstItem as any)?.keterangan && (firstItem as any)?.keterangan !== '-' ? String((firstItem as any)?.keterangan) : '')
    );
    setLines(
      isDownloadMode && Array.isArray(meta.items) && meta.items.length > 0
        ? meta.items.map((it: any, idx: number) => ({
            id: `${firstItem._id}-saved-${idx}`,
            program_name: String(it.program_name || ''),
            qty: String(Math.max(0, Number(it.qty) || 0)),
            unit_price: String(Math.max(0, Number(it.unit_price) || 0)),
            store_name: (firstItem.toko || '').toUpperCase(),
            include_store_suffix: false,
            start_date: resolveInvoiceStartDate(it as any),
            tempo_date: resolveInvoiceTempoDate(it as any),
          }))
        : items.map((it, idx) => ({
            id: `${it._id}-${idx}`,
            program_name: it.program || '',
            qty: String(it.bulan || 1),
            unit_price: String(it.harga || 0),
            store_name: (it.toko || '').toUpperCase(),
            include_store_suffix: true,
            start_date: resolveInvoiceStartDate(it as any),
            tempo_date: resolveInvoiceTempoDate(it as any),
          }))
    );
    setDiscountPercentText(String(isDownloadMode ? (meta.discount_percent || 0) : (firstItem.diskon_percent || 0)));
    setDiscountRpText(String(isDownloadMode ? (meta.discount_rp || 0) : (firstItem.diskon || 0)));
    setDiscountLabelText(String(isDownloadMode ? (meta.discount_label || 'DISC') : 'DISC').trim() || 'DISC');
    setExtraDeductionRpText(String(isDownloadMode ? (meta.extra_deduction_rp || 0) : ((firstItem as any)?.invoice_meta?.extra_deduction_rp || 0)));
    setLastDiscountEdit('percent');
    setPdfSnapshot(null);
    const paymentAccountMap = new Map(
      (paymentAccounts || []).map((acc: any, idx: number) => [
        getPaymentAccountLookupKey(acc),
        getPaymentAccountKey(acc, idx),
      ])
    );
    const metaPaymentAccounts = isDownloadMode && Array.isArray(meta.payment_accounts)
      ? meta.payment_accounts
      : [];
    const preselectedKeys = metaPaymentAccounts
      .map((acc: any) => paymentAccountMap.get(getPaymentAccountLookupKey(acc)))
      .filter((key: any): key is string => Boolean(key));
    setSelectedPaymentAccountKeys(preselectedKeys);
    setPaymentAccountPicker('');
  }, [open, items, subscribers, mode, paymentAccounts]);

  useEffect(() => {
    if (!open || !subscriberKode) return;
    if (customerPhone.trim() === initialPhone.trim()) return;
    const timer = setTimeout(async () => {
      try {
        await onAutoSavePhone({ kode: subscriberKode, nomor_telepon: customerPhone.trim() });
        setInitialPhone(customerPhone.trim());
      } catch {
        // keep silent to avoid noisy toasts while user typing
      }
    }, 700);
    return () => clearTimeout(timer);
  }, [open, subscriberKode, customerPhone, initialPhone, onAutoSavePhone]);

  const computedLines = useMemo(() => {
    return lines.map((line) => {
      const qty = Math.max(0, parseInt((line.qty || '').replace(/[^0-9]/g, ''), 10) || 0);
      const unitPrice = Math.max(0, parseCurrencyInput(line.unit_price || '0'));
      const lineTotal = qty * unitPrice;
      return {
        ...line,
        store_name: (line.store_name || '').toUpperCase(),
        include_store_suffix: !!line.include_store_suffix,
        qty,
        unit_price: unitPrice,
        line_total: lineTotal,
      };
    });
  }, [lines]);

  const subtotal = useMemo(
    () => computedLines.reduce((sum, line) => sum + line.line_total, 0),
    [computedLines]
  );

  const discountPercentParsed = useMemo(() => {
    const n = parseInt((discountPercentText || '').replace(/[^0-9]/g, ''), 10) || 0;
    return Math.max(0, Math.min(100, n));
  }, [discountPercentText]);
  const discountRpParsed = useMemo(() => Math.max(0, parseCurrencyInput(discountRpText || '0')), [discountRpText]);
  const extraDeductionRpParsed = useMemo(
    () => Math.max(0, parseCurrencyInput(extraDeductionRpText || '0')),
    [extraDeductionRpText]
  );

  const discountComputed = useMemo(() => {
    if (lastDiscountEdit === 'rp') {
      const rp = Math.min(subtotal, discountRpParsed);
      const pct = subtotal > 0 ? Math.round((rp / subtotal) * 10000) / 100 : 0;
      return { percent: pct, rp };
    }
    const percent = discountPercentParsed;
    const rp = Math.min(subtotal, Math.floor((subtotal * percent) / 100));
    return { percent, rp };
  }, [lastDiscountEdit, subtotal, discountRpParsed, discountPercentParsed]);

  const extraDeductionComputed = useMemo(
    () => Math.min(subtotal, extraDeductionRpParsed),
    [subtotal, extraDeductionRpParsed]
  );

  const grandTotal = Math.max(0, subtotal - discountComputed.rp - extraDeductionComputed);

  const handleAddLine = () => {
    setLines((prev) => [
      ...prev,
      {
        id: `${Date.now()}-${prev.length}`,
        program_name: '',
        qty: '1',
        unit_price: '0',
        store_name: customerName || '',
        include_store_suffix: true,
        start_date: '',
        tempo_date: '',
      },
    ]);
  };

  const selectedPaymentAccounts = useMemo(() => {
    const selectedSet = new Set(selectedPaymentAccountKeys);
    const selectedFromMaster = (paymentAccounts || [])
      .map((acc: any, idx: number) => ({ ...acc, __key: getPaymentAccountKey(acc as any, idx) }))
      .filter((acc: any) => selectedSet.has(acc.__key));

    if (selectedFromMaster.length > 0) return selectedFromMaster;

    const firstItemMetaAccounts = (items?.[0] as any)?.invoice_meta?.payment_accounts;
    if (mode === 'download' && Array.isArray(firstItemMetaAccounts) && firstItemMetaAccounts.length > 0) {
      return firstItemMetaAccounts
        .map((acc: any, idx: number) => ({
          kode_bank: String(acc?.kode_bank || '').trim(),
          no_rekening: String(acc?.no_rekening || '').trim(),
          nama_rekening: String(acc?.nama_rekening || '').trim(),
          __key: `meta-${idx}`,
        }))
        .filter((acc: any) => acc.no_rekening);
    }

    return [];
  }, [paymentAccounts, selectedPaymentAccountKeys, items, mode]);

  const handleGeneratePdf = async (
    snapshot: InvoiceSnapshot,
    chosenPaymentAccounts: Array<{ kode_bank?: string; no_rekening?: string; nama_rekening?: string }>
  ) => {
    const dateObj = new Date(snapshot.display_date || new Date().toISOString());
    const yy = String(dateObj.getFullYear()).slice(-2);
    const mm = String(dateObj.getMonth() + 1).padStart(2, '0');
    const dd = String(dateObj.getDate()).padStart(2, '0');
    const parsedNo = String(snapshot.invoice_number || '').split('/').pop() || '0001';
    const nomor = parsedNo.replace(/[^\d]/g, '') || '0001';
    const tokoName = sanitizeFilename(snapshot.customer.name || items?.[0]?.toko || 'INVOICE');
    const baseName = `FM${yy}${mm}${dd}-${nomor} ${tokoName}`;

    const generatePdfFile = (withWatermark: boolean, suffix: string) => {
      const fileName = `${baseName}${withWatermark ? ' (LUNAS)' : ''}.pdf`;
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'pt', format: 'a4' });
      const pageWidth = pdf.internal.pageSize.getWidth();
      const pageHeight = pdf.internal.pageSize.getHeight();
      const marginX = 36;
      const topMargin = 44;
      const bottomMargin = 28;
      const contentWidth = pageWidth - marginX * 2;
      const contentBottom = pageHeight - bottomMargin;

      const drawWatermark = () => {
        if (!withWatermark) return;
        pdf.setGState(pdf.GState({ opacity: 0.2 }));
        pdf.setTextColor(214, 90, 90);
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(120);
        const x = pageWidth / 2;
        const y = pageHeight / 2;
        pdf.text('LUNAS', x + 100, y + 120, { align: 'center', angle: 45 });
        pdf.setGState(pdf.GState({ opacity: 1 }));
        pdf.setTextColor(0, 0, 0);
      };

      const drawHeader = (headerStamp: 'ASLI' | 'COPY') => {
        let y = topMargin;
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(18);
        pdf.text('Faktur Maintenance', pageWidth / 2, y, { align: 'center' });
        y += 14;

        const leftHeaderText = [
          `No :      ${snapshot.invoice_number}`,
          '',
          `Tanggal : ${formatInvoiceDateLong(snapshot.display_date)}`,
        ].join('\n');

        const rightHeaderText = [
          'Kepada Yth,',
          '',
          `Toko/Tn/Ny : ${snapshot.customer.name || '-'}`,
          '',
          `Alamat : ${snapshot.customer.address || '-'}`,
          '',
          `Telepon : ${snapshot.customer.phone || '-'}`,
        ].join('\n');

        autoTable(pdf, {
          startY: y + 8,
          margin: { left: marginX, right: marginX },
          theme: 'plain',
          styles: {
            fontSize: 10,
            cellPadding: { top: 15, right: 2, bottom: 15, left: 2 },
            valign: 'top',
            overflow: 'linebreak',
            textColor: [0, 0, 0],
          },
          body: [[leftHeaderText, rightHeaderText]],
          columnStyles: {
            0: { cellWidth: contentWidth * 0.5, halign: 'left', fontStyle: 'bold' },
            1: { cellWidth: contentWidth * 0.5, halign: 'left', fontStyle: 'bold' },
          },
        });
        const headerBottomY = ((pdf as any).lastAutoTable?.finalY || (y + 8));
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(30);
        pdf.setTextColor(24, 163, 222);
        pdf.text(headerStamp === 'ASLI' ? 'A S L I' : 'C O P Y', marginX + 72, headerBottomY - 30);
        pdf.setTextColor(0, 0, 0);
        return headerBottomY;
      };

      const renderInvoiceSet = (headerStamp: 'ASLI' | 'COPY') => {
        const setStartPage = pdf.getNumberOfPages();
        const tableStartY = drawHeader(headerStamp);
        const itemRows = snapshot.items.map((it, idx) => [
          String(idx + 1),
          `${(it.program_name || '').replace(/\s*\n+\s*/g, ' ').replace(/\s{2,}/g, ' ').trim()}\nTerhitung :\n- ${formatInvoiceDateLong(resolveInvoiceStartDate(it as any))} s/d ${formatInvoiceDateLong(resolveInvoiceTempoDate(it as any))}`,
          `${Math.max(0, Number(it.qty) || 0)} bulan`,
          currency(it.unit_price),
          currency(it.line_total),
        ]);
        const noColW = 26;
        const restW = contentWidth - noColW;
        const signatureBlockH = 120;
        const terbilangBlockH = 42;
        const signRowIndex = itemRows.length;
        const terbilangRowIndex = signRowIndex + 1;

        const bodyRows: any[] = [
          ...itemRows,
          [
            { content: '', colSpan: 3, styles: { minCellHeight: signatureBlockH, valign: 'top' } },
            { content: '', colSpan: 2, styles: { minCellHeight: signatureBlockH, valign: 'top' } },
          ],
          [
            { content: '', colSpan: 5, styles: { minCellHeight: terbilangBlockH, valign: 'top' } },
          ],
        ];

        autoTable(pdf, {
          startY: tableStartY,
          margin: { left: marginX, right: marginX, top: topMargin, bottom: bottomMargin + 18 },
          head: [['No', 'NAMA BARANG', 'KUANTITI', 'HARGA/UNIT', 'TOTAL HARGA']],
          body: bodyRows,
          theme: 'grid',
          headStyles: {
            fillColor: [255, 255, 255],
            textColor: [0, 0, 0],
            lineColor: [125, 139, 158],
            lineWidth: 0.8,
            halign: 'center',
            fontStyle: 'bold',
          },
          styles: {
            fontSize: 10,
            cellPadding: 5,
             lineColor: [125, 139, 158],
            lineWidth: 0.8,
            valign: 'top',
          },
          columnStyles: {
            0: { cellWidth: noColW, halign: 'center' },
            1: { cellWidth: restW * 0.50, halign: 'left' },
            2: { cellWidth: restW * 0.12, halign: 'center' },
            3: { cellWidth: restW * 0.19, halign: 'right' },
            4: { cellWidth: restW * 0.19, halign: 'right' },
          },
          didDrawCell: (data) => {
            if (data.section !== 'body') return;

            if (data.row.index === signRowIndex && data.column.index === 0) {
              const x = data.cell.x;
              const yCell = data.cell.y;
              const w = data.cell.width;
              const leftHalf = x + w / 2;
              pdf.setFont('helvetica', 'normal');
              pdf.setFontSize(10);
              pdf.text('Hormat kami', x + 14, yCell + 22);
              pdf.text('Penerima', leftHalf + 10, yCell + 22);
              if (INVOICE_SIGNATURE_BASE64) {
                try {
                  pdf.addImage(INVOICE_SIGNATURE_BASE64, 'PNG', x + 14, yCell + 32, 90, 56);
                } catch {}
              }
              pdf.setFont('helvetica', 'bold');
              pdf.text('( ISMAHRIA S )', x + 14, yCell + 104);
              pdf.text('(..........................)', leftHalf + 10, yCell + 104);
              return;
            }

            if (data.row.index === signRowIndex && data.column.index === 3) {
              const x = data.cell.x;
              const yCell = data.cell.y;
              const w = data.cell.width;
              const hasDiscount = Number(snapshot.discount_rp || 0) > 0 || Number(snapshot.discount_percent || 0) > 0;
              const hasExtraDeduction = Number(snapshot.extra_deduction_rp || 0) > 0;
              const discountLabel = String(snapshot.discount_label || 'DISC').trim() || 'DISC';
              pdf.setFont('helvetica', 'bold');
              pdf.setFontSize(10);
              pdf.text('GRAND TOTAL', x + 10, yCell + 24);
              pdf.text(currency(snapshot.subtotal), x + w - 10, yCell + 24, { align: 'right' });
              let summaryY = yCell + 46;
              if (hasDiscount) {
                pdf.text(`${discountLabel} ${snapshot.discount_percent}%`, x + 10, summaryY);
                pdf.text(currency(snapshot.discount_rp), x + w - 10, summaryY, { align: 'right' });
                summaryY += 20;
              }
              if (hasExtraDeduction) {
                pdf.text('DISC TAMBAHAN', x + 10, summaryY);
                pdf.text(currency(snapshot.extra_deduction_rp || 0), x + w - 10, summaryY, { align: 'right' });
                summaryY += 20;
              }
              pdf.text('TOTAL', x + 10, summaryY + 8);
              pdf.text(currency(snapshot.grand_total), x + w - 10, summaryY + 8, { align: 'right' });
              return;
            }

            if (data.row.index === terbilangRowIndex && data.column.index === 0) {
              const x = data.cell.x;
              const yCell = data.cell.y;
              pdf.setFont('helvetica', 'bold');
              pdf.setFontSize(10);
              pdf.text('Terbilang :', x + 8, yCell + 16);
              pdf.setFont('helvetica', 'bolditalic');
              pdf.text(`#${toIndonesianWords(snapshot.grand_total)} rupiah#`.toUpperCase(), x + 8, yCell + 34);
            }
          },
        });

        let y = ((pdf as any).lastAutoTable?.finalY || tableStartY) + 14;
        const rekeningRows = (chosenPaymentAccounts.length > 0
          ? chosenPaymentAccounts
              .filter((r) => (r?.no_rekening || '').toString().trim().length > 0)
              .map((r) => [
                (r?.kode_bank || '-').toString(),
                (r?.no_rekening || '-').toString(),
                (r?.nama_rekening || snapshot.sender.name || 'PT. GRAHA INTEGRA APLIKASI').toString(),
              ])
          : [['BCA', '2839016888', snapshot.sender.name || 'PT. GRAHA INTEGRA APLIKASI']]
        ) as string[][];
        const paymentBlockH = 92 + rekeningRows.length * 20;
        if (y + paymentBlockH > contentBottom) {
          pdf.addPage();
          y = topMargin;
        }

        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(10);
        pdf.text('PEMBAYARAN DAPAT DITRANSFER MELALUI', marginX, y + 10);
        const bankTop = y + 14;
        autoTable(pdf, {
          startY: bankTop,
          margin: { left: marginX, right: marginX },
          theme: 'grid',
          styles: {
            fontSize: 9,
            cellPadding: { top: 5, right: 8, bottom: 5, left: 8 },
            lineColor: [125, 139, 158],
            lineWidth: 0.8,
            textColor: [0, 0, 0],
            valign: 'middle',
            fontStyle: 'bold',
          },
          body: rekeningRows,
          columnStyles: {
            0: { cellWidth: contentWidth * 0.25, halign: 'left' },
            1: { cellWidth: contentWidth * 0.30, halign: 'left' },
            2: { cellWidth: contentWidth * 0.45, halign: 'left' },
          },
        });
        const noteTop = (((pdf as any).lastAutoTable?.finalY || bankTop) as number) + 10;

        pdf.setFont('helvetica', 'bold');
        pdf.setTextColor(210, 20, 20);
        pdf.text('Catatan :', marginX, noteTop + 18);
        pdf.text('Jika tidak melakukan pembayaran lebih dari 14 hari sejak tanggal faktur diterbitkan, maka program akan', marginX, noteTop + 40);
        pdf.text('diputus sementara.', marginX, noteTop + 60);
        pdf.setTextColor(0, 0, 0);

        const setEndPage = pdf.getNumberOfPages();
        for (let i = setStartPage; i <= setEndPage; i += 1) {
          pdf.setPage(i);
          drawWatermark();
          pdf.setFont('helvetica', 'bold');
          pdf.setFontSize(10);
          pdf.text('***************** THANK YOU FOR YOUR BUSINESS *****************', pageWidth / 2, pageHeight - 20, { align: 'center' });
        }
      };

      renderInvoiceSet('ASLI');
      pdf.addPage();
      renderInvoiceSet('COPY');
      pdf.save(fileName);
    };

    generatePdfFile(true, 'WATERMARK');
    generatePdfFile(false, 'NO WATERMARK');
  };

  const handleSubmit = async () => {
    if (!items.length) return;
    const validLines = computedLines.filter((line) => line.program_name.trim() && line.qty > 0);
    if (validLines.length === 0) return toast.error('Minimal ada 1 item invoice valid.');
    if (!customerName.trim()) return toast.error('Nama toko wajib diisi.');
    if (!displayDate) return toast.error('Tanggal invoice wajib diisi.');
    if (selectedPaymentAccounts.length === 0) return toast.error('Pilih minimal 1 rekening untuk footer pembayaran.');

    setCreating(true);
    try {
      const snapshot = await onGenerate({
        customer: {
          name: customerName.trim(),
          address: customerAddress.trim(),
          phone: customerPhone.trim(),
        },
        payment_accounts: selectedPaymentAccounts.map((acc) => ({
          kode_bank: String(acc?.kode_bank || '').trim(),
          no_rekening: String(acc?.no_rekening || '').trim(),
          nama_rekening: String(acc?.nama_rekening || '').trim(),
        })).filter((acc) => acc.no_rekening),
        items: validLines.map((line) => ({
          // Reprint/download should keep stored program name as-is to avoid double prefix.
          program_name: mode === 'download'
            ? String(line.program_name || '').trim().replace(/\s{2,}/g, ' ')
            : formatInvoiceProgramName(line.program_name, {
                includeStoreSuffix: line.include_store_suffix,
                storeName: line.store_name,
              }),
          qty: line.qty,
          unit_price: line.unit_price,
          line_total: line.line_total,
          start_date: resolveInvoiceStartDate(line as any),
          tempo_date: resolveInvoiceTempoDate(line as any),
        })),
        discount_label: String(discountLabelText || 'DISC').trim() || 'DISC',
        discount_percent: discountComputed.percent,
        discount_rp: discountComputed.rp,
        extra_deduction_rp: extraDeductionComputed,
        subtotal,
        grand_total: grandTotal,
        notes: notes.trim(),
        display_date: displayDate,
      });

      await handleGeneratePdf(snapshot, selectedPaymentAccounts);
      toast.success('Invoice berhasil digenerate.');
      onOpenChange(false);
    } catch (e: any) {
      toast.error(e?.response?.data?.message || e?.message || 'Gagal generate invoice.');
    } finally {
      setCreating(false);
    }
  };

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="sm:max-w-[1100px] w-[96vw] max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{mode === 'download' ? 'Download Ulang Invoice VPS' : 'Generate Invoice VPS'}</DialogTitle>
          </DialogHeader>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-1 md:col-span-1">
              <Label>Nama Toko</Label>
              <Input value={customerName} onChange={(e) => setCustomerName(e.target.value.toUpperCase())} />
            </div>
            <div className="space-y-1 md:col-span-1">
              <Label>Nomor Telefon</Label>
              <Input value={customerPhone} onChange={(e) => setCustomerPhone(e.target.value)} />
            </div>
            <div className="space-y-1 md:col-span-1">
              <Label>Tanggal</Label>
              <Input type="date" value={displayDate} onChange={(e) => setDisplayDate(e.target.value)} />
            </div>
            <div className="space-y-1 md:col-span-3">
              <Label>Alamat Toko</Label>
              <Input value={customerAddress} onChange={(e) => setCustomerAddress(e.target.value)} />
            </div>
          </div>

          <div className="rounded-md border mt-3 p-3 space-y-3">
            <Label className="font-semibold">Rekening Footer Pembayaran</Label>
            <Select
              value={paymentAccountPicker || undefined}
              onValueChange={(val) => {
                setPaymentAccountPicker(val);
                setSelectedPaymentAccountKeys((prev) => (prev.includes(val) ? prev : [...prev, val]));
                setTimeout(() => setPaymentAccountPicker(''), 0);
              }}
              disabled={(paymentAccounts || []).length === 0}
            >
              <SelectTrigger>
                <SelectValue placeholder="Pilih rekening untuk ditambahkan" />
              </SelectTrigger>
              <SelectContent>
                {(paymentAccounts || []).map((acc: any, idx: number) => {
                  const key = getPaymentAccountKey(acc, idx);
                  return (
                    <SelectItem key={key} value={key}>
                      {(acc?.kode_bank || '-')} - {(acc?.no_rekening || '-')}
                      {acc?.nama_rekening ? ` (${acc.nama_rekening})` : ''}
                    </SelectItem>
                  );
                })}
              </SelectContent>
            </Select>

            {selectedPaymentAccounts.length > 0 ? (
              <div className="flex flex-wrap gap-3">
                {selectedPaymentAccounts.map((acc: any) => {
                  const key = acc.__key as string;
                  return (
                    <div
                      key={key}
                      className="inline-flex items-center gap-3 rounded-lg border-2 border-blue-200 bg-blue-50 px-3 py-2 text-sm font-semibold text-blue-900 shadow-sm"
                    >
                      <span className="whitespace-nowrap">
                        {(acc?.kode_bank || '-')} - {(acc?.no_rekening || '-')}
                        {acc?.nama_rekening ? ` • ${acc.nama_rekening}` : ''}
                      </span>
                      <button
                        type="button"
                        className="inline-flex h-6 w-6 items-center justify-center rounded-full bg-white text-red-600 hover:bg-red-50 hover:text-red-700 border border-red-200"
                        onClick={() => setSelectedPaymentAccountKeys((prev) => prev.filter((k) => k !== key))}
                      >
                        ×
                      </button>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="text-xs text-gray-500">Belum ada rekening dipilih.</div>
            )}
          </div>

          <div className="rounded-md border mt-2">
            <div className="p-3 border-b font-semibold flex justify-between items-center">
              <span>Data Barang Invoice</span>
              <Button type="button" size="sm" variant="outline" onClick={handleAddLine}>Tambah Baris</Button>
            </div>
            <div className="overflow-x-auto p-3">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b">
                    <th className="text-left py-2 pr-2 w-[46%]">Nama Program</th>
                    <th className="text-left py-2 pr-2 w-24">Kuantiti</th>
                    <th className="text-center py-2 px-1 w-16">Suffix Toko</th>
                    <th className="text-left py-2 pr-2 w-40">Harga/Unit</th>
                    <th className="text-left py-2 pr-2 w-40">Total Harga</th>
                    <th className="text-left py-2 w-16">Aksi</th>
                  </tr>
                </thead>
                <tbody>
                  {computedLines.map((line, idx) => (
                    <tr key={line.id} className="border-b last:border-b-0">
                      <td className="py-2 pr-2">
                        <Input
                          value={lines[idx]?.program_name || ''}
                          onChange={(e) => setLines((prev) => prev.map((p, i) => i === idx ? { ...p, program_name: e.target.value.toUpperCase() } : p))}
                          placeholder="Nama program"
                        />
                      </td>
                      <td className="py-2 pr-2">
                        <Input
                          inputMode="numeric"
                          value={lines[idx]?.qty || ''}
                          onChange={(e) => setLines((prev) => prev.map((p, i) => i === idx ? { ...p, qty: e.target.value.replace(/[^0-9]/g, '') } : p))}
                        />
                      </td>
                      <td className="py-2 pr-2">
                        <label className="flex items-center justify-center">
                          <input
                            type="checkbox"
                            checked={!!lines[idx]?.include_store_suffix}
                            onChange={(e) => setLines((prev) => prev.map((p, i) => i === idx ? { ...p, include_store_suffix: e.target.checked } : p))}
                            className="h-4 w-4"
                          />
                        </label>
                      </td>
                      <td className="py-2 pr-2">
                        <Input
                          inputMode="numeric"
                          value={currency(line.unit_price)}
                          onChange={(e) => setLines((prev) => prev.map((p, i) => i === idx ? { ...p, unit_price: String(parseCurrencyInput(e.target.value)) } : p))}
                        />
                      </td>
                      <td className="py-2 pr-2">
                        <Input value={currency(line.line_total)} readOnly />
                      </td>
                      <td className="py-2">
                        <Button
                          type="button"
                          size="sm"
                          variant="ghost"
                          className="text-red-600 hover:text-red-700"
                          disabled={lines.length <= 1}
                          onClick={() => setLines((prev) => prev.filter((_, i) => i !== idx))}
                        >
                          Hapus
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="space-y-1">
                <Label>Nama Diskon</Label>
                <Input
                  value={discountLabelText}
                  onChange={(e) => setDiscountLabelText(e.target.value.toUpperCase())}
                  placeholder="DISC"
                />
              </div>
              <div className="space-y-1">
                <Label>Diskon (%)</Label>
                <Input
                  inputMode="numeric"
                  value={discountPercentText}
                  onChange={(e) => {
                    setLastDiscountEdit('percent');
                    setDiscountPercentText(e.target.value.replace(/[^0-9]/g, ''));
                  }}
                />
              </div>
              <div className="space-y-1">
                <Label>Diskon (Rp)</Label>
                <Input
                  inputMode="numeric"
                  value={currency(discountComputed.rp)}
                  onChange={(e) => {
                    setLastDiscountEdit('rp');
                    setDiscountRpText(String(parseCurrencyInput(e.target.value)));
                  }}
                />
              </div>
              <div className="space-y-1">
                <Label>Subtotal</Label>
                <Input value={currency(subtotal)} readOnly />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <Label>Potongan Tambahan (Rp)</Label>
                <Input
                  inputMode="numeric"
                  value={currency(extraDeductionComputed)}
                  onChange={(e) => setExtraDeductionRpText(String(parseCurrencyInput(e.target.value)))}
                />
              </div>
              <div className="space-y-1">
                <Label>Total Akhir</Label>
                <Input value={currency(grandTotal)} readOnly />
              </div>
            </div>

            <div className="space-y-1">
              <Label>Keterangan</Label>
              <Input value={notes} onChange={(e) => setNotes(e.target.value.toUpperCase())} placeholder="Catatan tambahan..." />
            </div>
          </div>

          <div className="flex justify-end gap-2">
            <Button type="button" variant="secondary" onClick={() => onOpenChange(false)}>Batal</Button>
            <Button type="button" onClick={handleSubmit} disabled={creating}>
              {creating ? 'Generating...' : mode === 'download' ? 'Download Invoice' : 'Generate Invoice'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      <div className="fixed -left-[99999px] top-0 w-[794px] bg-white p-6 text-black" ref={templateRef}>
        {pdfSnapshot ? <InvoicePdfTemplate invoice={pdfSnapshot} /> : null}
      </div>
    </>
  );
}

function InvoicePdfTemplate({ invoice }: { invoice: InvoiceSnapshot }) {
  const terbilang = `#${toIndonesianWords(invoice.grand_total)} rupiah#`.toUpperCase();
  return (
    <div className="w-full relative text-[14px] leading-relaxed">
      <div className="text-center font-bold text-2xl mt-8 mb-8">Faktur Maintenance</div>
      <div className="grid grid-cols-2 gap-6 mb-6">
        <div className="space-y-2">
          <div><span className="font-semibold mr-2">No :</span> {invoice.invoice_number}</div>
          <div><span className="font-semibold mr-2">Tanggal :</span> {invoice.display_date ? new Date(invoice.display_date).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }) : '-'}</div>
        </div>
        <div className="space-y-1">
          <div className="font-semibold">Kepada Yth,</div>
          <div><span className="font-semibold mr-2">Toko/Tn/Ny :</span> {invoice.customer.name}</div>
          <div><span className="font-semibold mr-2">Alamat :</span> {invoice.customer.address || '-'}</div>
          <div><span className="font-semibold mr-2">Telepon :</span> {invoice.customer.phone || '-'}</div>
        </div>
      </div>

      <div className="border border-slate-500">
        <table className="w-full text-[13px]">
          <thead>
            <tr className="border-b border-slate-500">
              <th className="w-10 border-r border-slate-500 p-2">No</th>
              <th className="w-[50%] border-r border-slate-500 p-2">NAMA BARANG</th>
              <th className="w-[10%] border-r border-slate-500 p-2">KUANTITI</th>
              <th className="w-[20%] border-r border-slate-500 p-2">HARGA/UNIT</th>
              <th className="w-[20%] p-2">TOTAL HARGA</th>
            </tr>
          </thead>
          <tbody>
            {invoice.items.map((it, idx) => (
              <tr key={`${it.program_name}-${idx}`} className="border-b border-slate-300">
                <td className="border-r border-slate-300 p-2 align-top text-center">{idx + 1}</td>
                <td className="border-r border-slate-300 p-2 align-top">
                  {(() => {
                    const mainText = (it.program_name || '').replace(/\s*\n+\s*/g, ' ').replace(/\s{2,}/g, ' ').trim();
                    const isShort = mainText.split(' ').filter(Boolean).length <= 2;
                    return (
                      <div
                        style={{
                          textAlign: isShort ? 'left' : 'justify',
                          textJustify: 'inter-word',
                          textAlignLast: isShort ? 'left' : 'justify',
                          lineHeight: 1.35,
                        }}
                      >
                        {mainText}
                      </div>
                    );
                  })()}
                  <div
                    className="mt-1 whitespace-pre-line"
                  >
                    <div>Terhitung :</div>
                    <div>- {formatInvoiceDateLong(resolveInvoiceStartDate(it as any))} s/d {formatInvoiceDateLong(resolveInvoiceTempoDate(it as any))}</div>
                  </div>
                </td>
                <td className="border-r border-slate-300 p-2 align-top text-center">{Math.max(0, Number(it.qty) || 0)} bulan</td>
                <td className="border-r border-slate-300 p-2 align-top text-right">{currency(it.unit_price)}</td>
                <td className="p-2 align-top text-right">{currency(it.line_total)}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <div className="border-t border-slate-500 grid grid-cols-2">
          <div className="p-1">
            <div className="grid grid-cols-2 gap-4">
              <div className="text-center text-[15px]">Hormat kami</div>
              <div className="text-center text-[15px]">Penerima</div>
            </div>
            <div className="grid grid-cols-2 gap-4 mt-2 min-h-[90px]">
              <div className="flex items-center justify-center">
                {INVOICE_SIGNATURE_BASE64 ? (
                  <img src={INVOICE_SIGNATURE_BASE64} alt="Tanda tangan" className="max-h-[82px] object-contain" />
                ) : null}
              </div>
              <div />
            </div>
            <div className="grid grid-cols-2 gap-4 mt-1 mb-3">
              <div className="text-center font-semibold">( ISMAHRIA S )</div>
              <div className="text-center font-semibold">(..........................)</div>
            </div>
          </div>
          <div className="p-3 border-l border-slate-500">
            <div className="flex justify-between font-semibold"><span>GRAND TOTAL</span><span>{currency(invoice.subtotal)}</span></div>
            {(Number(invoice.discount_rp || 0) > 0 || Number(invoice.discount_percent || 0) > 0) ? (
              <div className="flex justify-between font-semibold"><span>{(String(invoice.discount_label || 'DISC').trim() || 'DISC')} {invoice.discount_percent}%</span><span>{currency(invoice.discount_rp)}</span></div>
            ) : null}
            {Number(invoice.extra_deduction_rp || 0) > 0 ? (
              <div className="flex justify-between font-semibold"><span>DISC TAMBAHAN</span><span>{currency(invoice.extra_deduction_rp || 0)}</span></div>
            ) : null}
            <div className="flex justify-between font-bold text-lg"><span>TOTAL</span><span>{currency(invoice.grand_total)}</span></div>
          </div>
        </div>
        <div data-invoice-footer-block className="border-t border-slate-500 p-2">
          <div className="font-semibold">Terbilang :</div>
          <div className="italic font-semibold">{terbilang}</div>
        </div>
      </div>

      <div className="mt-6">
        <div className="text-sm">PEMBAYARAN DAPAT DITRANSFER MELALUI</div>
        <div className="grid grid-cols-3 border border-slate-500 mt-1 text-sm font-semibold">
          <div className="p-2 border-r border-slate-500">BANK BCA</div>
          <div className="p-2 border-r border-slate-500">2839016888</div>
          <div className="p-2">{invoice.sender.name}</div>
        </div>

        <div className="mt-6 text-red-600 font-bold">
          <div>Catatan :</div>
          <div>Jika tidak melakukan pembayaran lebih dari 14 hari sejak tanggal faktur diterbitkan, maka program akan diputus sementara.</div>
        </div>
      </div>
    </div>
  );
}

function VpsItemPreview({ item }: { item: any }) {
  const jumlah = (Number(item?.harga) || 0) * (Number(item?.bulan) || 0);
  const diskonPercent = Number(item?.diskon_percent) || 0;
  const diskonRp = Number(item?.diskon) || 0;
  const total = Number(item?.total_harga) || Math.max(0, jumlah - diskonRp);
  return (
    <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
      <div>
        <div className="text-xs text-slate-500">Toko</div>
        <div className="text-sm font-medium">{item?.toko}</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Program</div>
        <div className="text-sm font-medium">{item?.program}</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Daerah</div>
        <div className="text-sm font-medium">{item?.daerah}</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Start Date</div>
        <div className="text-sm font-medium">{item?.start ? format(new Date(item.start), 'dd MMM yyyy') : '-'}</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Bulan</div>
        <div className="text-sm font-medium">{item?.bulan}</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Tempo</div>
        <div className="text-sm font-medium">{item?.tempo ? format(new Date(item.tempo), 'dd MMM yyyy') : '-'}</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Harga/Bln</div>
        <div className="text-sm font-medium">{currency(Number(item?.harga) || 0)}</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Jumlah Harga</div>
        <div className="text-sm font-medium">{currency(jumlah)}</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Diskon (%)</div>
        <div className="text-sm font-medium">{diskonPercent}%</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Diskon (Rp)</div>
        <div className="text-sm font-medium">{currency(diskonRp)}</div>
      </div>
      <div>
        <div className="text-xs text-slate-500">Total Harga</div>
        <div className="text-sm font-medium">{currency(total)}</div>
      </div>
    </div>
  );
}

function ConfirmAction({ title, description, actionText, onConfirm, children, showDate, preview }: { title: string; description: string; actionText: string; onConfirm: (date?: string) => void; children: React.ReactElement; showDate?: boolean; preview?: React.ReactNode }) {
  const [date, setDate] = useState<string>('');
  return (
    <AlertDialog>
      <AlertDialogTrigger asChild>{children}</AlertDialogTrigger>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        {preview ? (
          <div className="my-3 p-3 border rounded bg-slate-50">
            {preview}
          </div>
        ) : null}
        {showDate && (
          <div className="my-2">
            <Label htmlFor="tanggal-lunas">Tanggal Lunas</Label>
            <Input id="tanggal-lunas" type="date" value={date} onChange={e => setDate(e.target.value)} />
          </div>
        )}
        <AlertDialogFooter>
          <AlertDialogCancel>Batal</AlertDialogCancel>
          <AlertDialogAction onClick={() => onConfirm(showDate ? date : undefined)} disabled={!!showDate && !date}>{actionText}</AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}
